	private EvaluationStrategy createEvaluationStrategy(Model m) {
		return createEvaluationStrategy(m, null);
	}

	private EvaluationStrategy createEvaluationStrategy(Model m, AtomicInteger closes) {
		TripleSource ts = new TripleSource() {

			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subj,
					IRI pred, Value obj, Resource... contexts) throws QueryEvaluationException {
				return new CloseableIteratorIteration<>(m.getStatements(subj, pred, obj, contexts).iterator()) {
					@Override
					protected void handleClose() {
						if (closes != null) {
							closes.incrementAndGet();
						}
					}
				};
			}

			@Override
			public ValueFactory getValueFactory() {
				return vf;
			}
		};
		return new StrictEvaluationStrategy(ts, null);
	}

	/**
	 * Verify that evaluation of a {@link ZeroLengthPathIteration} does not discard input bindings.
	 *
	 * @see <a href="https://github.com/eclipse/rdf4j/issues/689">GH-689</a>
	 */
	@Test
	public void testRetainInputBindings() {

		MapBindingSet bindings = new MapBindingSet();
		bindings.addBinding("a", RDF.FIRST);

		Var subjectVar = Var.of("x");
		Var objVar = Var.of("y");
		try (ZeroLengthPathIteration zlp = new ZeroLengthPathIteration(evaluator, subjectVar, objVar, null, null, null,
				bindings, new QueryEvaluationContext.Minimal(null))) {
			BindingSet result = zlp.getNextElement();

			assertTrue(result.hasBinding("a"), "zlp evaluation should have retained unrelated input binding");
			assertTrue(result.hasBinding("x"), "zlp evaluation should binding for subject var");
			assertTrue(result.hasBinding("y"), "zlp evaluation should binding for object var");
		}
	}

	@Test
	public void recordsZeroLengthPathExplorationTelemetry() {
		Var subjectVar = Var.of("x");
		Var objVar = Var.of("y");
		ZeroLengthPath node = new ZeroLengthPath(subjectVar.clone(), objVar.clone());
		node.setRuntimeTelemetryEnabled(true);
		try (ZeroLengthPathIteration zlp = new ZeroLengthPathIteration(evaluator, node, subjectVar, objVar, null, null,
				null, new MapBindingSet(), new QueryEvaluationContext.Minimal(null))) {
			assertNotNull(zlp.getNextElement());
		}
		assertTrue(node.getLongMetricActual(ZeroLengthPathIteration.ZERO_LENGTH_CANDIDATE_ROWS_ACTUAL) > 0L);
		assertTrue(node.getLongMetricActual(ZeroLengthPathIteration.ZERO_LENGTH_RETURNED_ROWS_ACTUAL) > 0L);
	}

